1211		\label{lem:restricted-line-mixture-bounds}
1212		\lean{MIPStarRE.QPBT.linePointDist_eq_mixture_restricted}
1213		\lean{MIPStarRE.QPBT.avg_restricted_le, MIPStarRE.QPBT.avg_restricted_prod_le}
