1218		% references/qpbt-paper/14_analysis_of_the_pauli_basis_test.tex.
1219		\uses{def:ith-restricted-line, def:line-point-dist, lem:qld-xz-lines,
1220			lem:qld-4-10, def:expanded-state}
1221		The distribution $D_{\mathrm{ALine}}$ is a uniform mixture of the
1222		distributions $D_{\mathrm{ALine},i}$ for $i \in \{1, \dots, m\}$, and
1223		likewise $D_{\mathrm{DLine}}$ is a uniform mixture of the
1224		$D_{\mathrm{DLine},i}$. As a consequence:
1225		\begin{enumerate}
1226			\item any approximation that holds on average over the line-point
1227			distribution $D_{\mathrm{Line}}$ with error $\delta$ holds over each
1228			restricted distribution $D_{\mathrm{ALine},i}$ and
1229			$D_{\mathrm{DLine},i}$ with error $2m\delta$;
1230			\item any approximation that holds on average over
1231			$D_{\mathrm{Line}} \times D_{\mathrm{Line}}$ holds over any product
1232			of restricted distributions with error $4m^2\delta$;
1233			\item in particular, by Lemma~\ref{lem:qld-xz-lines}, for any types
1234			$\mathrm{v}_1, \mathrm{v}_2 \in \{\mathrm{ALine},
1235			\mathrm{DLine}\}$ and any $i, j \in \{1, \dots, m\}$,
1236			\begin{equation}
1237				\label{eq:qld-xz-lines-restricted}
1238				\E_{(\ell_X,x) \sim D_{\mathrm{v}_1,i}}\
1239				\E_{(\ell_Z,z) \sim D_{\mathrm{v}_2,j}}
1240				\sum_{f_X,f_Z}
1241				\bra{\hat\psi}
1242				\big(T^{\ell_X,\ell_Z}_{f_X,f_Z}\big)_{\mathsf{A}\mathsf{A}'}
1243				\ot
1244				\big(\Id - \hat{Q}^{x,z}_{f_X(x),f_Z(z)}
1245				\big)_{\mathsf{B}\mathsf{A}''}
1246				\ket{\hat\psi}
1247				= O(m^2 \delta_P)\,.
1248			\end{equation}
1249		\end{enumerate}
1250	\end{lemma}
1251	\begin{proof}
1252		\uses{lem:qld-xz-lines, def:line-point-dist, def:consistency}
1253		The line-point distribution places weight $\tfrac{1}{2}$ on each of the
1254		axis-parallel and diagonal components and, within each component, uniform
1255		weight on the index $i$, so each restricted distribution carries mixture
1256		weight $\tfrac{1}{2m}$ in $D_{\mathrm{Line}}$. A nonnegative average that
1257		is at most $\delta$ therefore bounds each mixture component by
1258		$2m\delta$, and products of two such mixtures give the factor
1259		$(2m)^2 = 4m^2$. The instance \eqref{eq:qld-xz-lines-restricted} is item
1260		2 applied to the conclusion of Lemma~\ref{lem:qld-xz-lines}, whose
1261		$\simeq_{\delta_P}$ relation over two independent copies of the
1262		line-point distribution is precisely the statement that the left-hand
1263		side of \eqref{eq:qld-xz-lines-restricted}, averaged over
1264		$D_{\mathrm{Line}} \times D_{\mathrm{Line}}$, is at most $\delta_P$.
1265	\end{proof}
